void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 background = vec3(0.5);
    vec3 linecolour = vec3(0.961,0.761,0.067);
    vec2 uv = (fragCoord/iResolution.xy)*2. -1.;
    uv.x *= iResolution.x/iResolution.y;
    uv *= 4.; //scale 
    float val = uv.x; 
    // Input equation ///////// 
    float equation = fract(val+iTime) * sin(val);
    ///////////////////////////
    float final = 1.- smoothstep(0.19,0.2, abs(uv.y -equation));

    vec3 col = background;
    col = mix(col,linecolour,final);

    // Output to screen
    fragColor = vec4(col,1.0);
}
